pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory tos, uint256[] memory vs) public {
        vm.assume(tos.length > 0 && tos.length == vs.length);
        vm.assume(from != address(0) && caddress != address(0));
        // Deploy a simple ERC20-like token to caddress for testing
        Token token = new Token();
        // Fund from with tokens
        token.mint(from, 1000000 ether);
        vm.prank(from);
        token.approve(address(c), type(uint256).max);

        uint256 totalValue;
        for (uint i = 0; i < vs.length; i++) {
            totalValue += vs[i];
        }
        vm.assume(totalValue <= token.balanceOf(from));

        uint256 balanceBefore = token.balanceOf(from);
        // Call transfer on C, which will attempt to transfer tokens via transferFrom
        c.transfer(from, address(token), tos, vs);
        uint256 balanceAfter = token.balanceOf(from);
        uint256 actualTransferred = balanceBefore - balanceAfter;

        // General rule: the actual amount transferred from 'from' equals the sum of requested values
        assertTrue(actualTransferred == totalValue, "Transfer amount mismatch");
    }
}

// Minimal ERC20 token for testing
contract Token {
    string public name = "Test";
    string public symbol = "TST";
    uint8 public decimals = 18;
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    function mint(address to, uint256 amount) external {
        balanceOf[to] += amount;
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        require(allowance[from][msg.sender] >= amount);
        allowance[from][msg.sender] -= amount;
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        return true;
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        return true;
    }
}

