pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    // Helper token to track balances
    IERC20 token;

    function setUp() public {
        c = new C();
        // Deploy a simple ERC20 token for testing
        token = new IERC20();
    }

    function testFuzz_property(address from, address[] memory _tos, uint256[] memory v) public {
        // Ensure array lengths match
        require(_tos.length > 0);
        vm.assume(_tos.length == v.length);

        // Ensure from address is not zero
        vm.assume(from != address(0));

        // Initialize balances: give from tokens
        uint256 totalValue = 0;
        for (uint256 i = 0; i < v.length; i++) {
            totalValue += v[i];
        }
        vm.deal(from, totalValue);

        // Record initial balance of from
        uint256 initialBalance = token.balanceOf(from);

        // Perform transfer
        c.transfer(from, address(token), _tos, v);

        // Calculate final balance of from
        uint256 finalBalance = token.balanceOf(from);

        // Rule: the balance decrease should equal total transferred value
        uint256 totalSent = 0;
        for (uint256 i = 0; i < _tos.length; i++) {
            totalSent += v[i];
        }

        // The reference should satisfy: initialBalance - finalBalance == totalSent
        assertTrue(initialBalance - finalBalance == totalSent);
    }
}

